mod calculator;
mod cli;
mod display;
mod repl;

fn main() {
    let opts = match cli::parse() {
        Ok(o) => o,
        Err(code) => std::process::exit(code),
    };
    if let Some(input) = opts.input.as_ref().filter(|s| !s.is_empty()) {
        match calculator::calculate(input, Some(0.0), opts.radians) {
            Ok(value) => println!("{}", display::number(value, opts.fix, opts.base)),
            Err(error) => {
                eprintln!("{}", error);
                std::process::exit(1);
            }
        }
    } else {
        repl::run(&opts);
    }
}
