cat > src/calculator.rs <<'EOF'
use std::collections::HashMap;
use std::f64::consts::{E, PI};

pub const PARSER: &str = "Parser Error: Too many operators, too few operands";
pub const PARENS: &str = "Syntax Error: Mismatched parentheses!";
pub const DOMAIN: &str = "Domain Error: Out of bounds!";

pub const FUNCTIONS: &[&str] = &[
    "sin", "cos", "tan", "csc", "sec", "cot", "sinh", "cosh", "tanh",
    "asin", "acos", "atan", "acsc", "asec", "acot", "ln", "log2", "log10",
    "sqrt", "ceil", "floor", "abs", "log", "nroot", "round", "exp", "exp2", "rad", "deg",
];

#[derive(Clone, Debug)]
enum Token {
    Number(f64),
    Op(char, bool), // the flag denotes a prefix unary operator
    Function(String),
    Left,
    Right,
    Comma,
}

fn constant(s: &str) -> Option<f64> {
    match s { "pi" => Some(PI), "e" => Some(E), _ => None }
}
fn function(s: &str) -> bool { FUNCTIONS.contains(&s) }
fn too_large() -> String { format!("Error: to large to process! Max value: {}", f64::MAX) }

pub fn help() -> String {
    // These are intentionally unordered, as is the REPL's listing.
    let constants: HashMap<&str, ()> = ["pi", "e"].iter().map(|&k| (k, ())).collect();
    let funcs: HashMap<&str, ()> = FUNCTIONS.iter().map(|&k| (k, ())).collect();
    let ops: HashMap<char, ()> = ['+', '-', '*', '/', '^', '!', '%'].iter().map(|&k| (k, ())).collect();
    let mut s = String::from("Constants\n");
    for k in constants.keys() { s.push_str(&format!("{:>8}", k)); }
    s.push_str("\n\nFunctions\n");
    for (i, k) in funcs.keys().enumerate() {
        s.push_str(&format!("{:>8}", k));
        if (i+1) % 9 == 0 { s.push('\n'); }
    }
    if funcs.len() % 9 != 0 { s.push('\n'); }
    s.push_str("\nOperators\n");
    for (i, k) in ops.keys().enumerate() {
        if i != 0 { s.push(' '); }
        s.push(*k);
    }
    s.push('\n');
    s
}

fn flush_number(buf: &mut String, tokens: &mut Vec<Token>) -> bool {
    let parsed = buf.parse::<f64>().ok();
    buf.clear();
    if let Some(x) = parsed { tokens.push(Token::Number(x)); true } else { false }
}
fn flush_constant(buf: &mut String, tokens: &mut Vec<Token>) -> bool {
    if let Some(x) = constant(buf) { tokens.push(Token::Number(x)); buf.clear(); true } else { false }
}

fn lex(input: &str, previous: Option<f64>) -> Result<Vec<Token>, String> {
    let mut tokens = Vec::new();
    let mut digits = String::new();
    let mut name = String::new();
    let mut unary_allowed = true;
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '0'..='9' | '.' => {
                if !name.is_empty() {
                    if (name == "log" && (c == '1' || c == '2')) ||
                       (name == "log1" && c == '0') || (name == "exp" && c == '2') {
                        name.push(c);
                    } else if let Some(x) = constant(&name) {
                        tokens.push(Token::Number(x));
                        tokens.push(Token::Op('*', false));
                        name.clear();
                        digits.push(c);
                    } else if function(&name) {
                        return Err(format!("Syntax Error: Function '{}' expected parentheses", name));
                    } else {
                        return Err(format!("Syntax Error: Unexpected character '{}{}'", name, c));
                    }
                } else {
                    digits.push(c);
                }
                unary_allowed = false;
            }
            'a'..='z' | 'A'..='Z' => {
                if flush_number(&mut digits, &mut tokens) {
                    tokens.push(Token::Op('*', false));
                }
                name.push(c);
                unary_allowed = false;
            }
            '_' => {
                if !name.is_empty() {
                    return Err(if function(&name) {
                        format!("Syntax Error: Function '{}' expected parentheses", name)
                    } else {
                        format!("Syntax Error: Unexpected character '{}'", name)
                    });
                }
                if flush_number(&mut digits, &mut tokens) {
                    tokens.push(Token::Op('*', false));
                }
                tokens.push(Token::Number(previous.ok_or("Syntax Error: No previous answer!")?));
                unary_allowed = false;
            }
            '(' => {
                if !name.is_empty() {
                    if !function(&name) { return Err(format!("Syntax Error: Unknown function '{}'", name)); }
                    tokens.push(Token::Function(std::mem::take(&mut name)));
                } else if flush_number(&mut digits, &mut tokens) || matches!(tokens.last(), Some(Token::Right)) {
                    tokens.push(Token::Op('*', false));
                }
                tokens.push(Token::Left);
                unary_allowed = true;
            }
            ')' => {
                flush_number(&mut digits, &mut tokens);
                flush_constant(&mut name, &mut tokens);
                tokens.push(Token::Right);
                unary_allowed = false;
            }
            ',' => {
                flush_number(&mut digits, &mut tokens);
                flush_constant(&mut name, &mut tokens);
                tokens.push(Token::Comma);
                unary_allowed = false;
            }
            '+' | '-' | '*' | '/' | '^' | '%' | '!' => {
                flush_number(&mut digits, &mut tokens);
                flush_constant(&mut name, &mut tokens);
                let mut op = c;
                if c == '*' && chars.get(i + 1) == Some(&'*') {
                    op = '^'; i += 1;
                }
                let prefix = unary_allowed && matches!(op, '+' | '-' | '!');
                tokens.push(Token::Op(op, prefix));
                unary_allowed = op != '!';
            }
            _ => return Err(format!("Syntax Error: Unexpected token: '{}'", c)),
        }
        i += 1;
    }
    flush_number(&mut digits, &mut tokens);
    flush_constant(&mut name, &mut tokens);
    Ok(tokens)
}

fn precedence(t: &Token) -> u8 {
    match t {
        Token::Op('+', false) | Token::Op('-', false) => 1,
        Token::Op('*', false) | Token::Op('/', false) | Token::Op('%', false) => 2,
        Token::Op('^', false) => 3,
        Token::Op(_, true) | Token::Op('!', false) => 4,
        _ => 0,
    }
}
fn right_associative(t: &Token) -> bool {
    matches!(t, Token::Op('^', _) | Token::Op('+', true) | Token::Op('-', true))
}

fn postfix(tokens: Vec<Token>) -> Result<Vec<Token>, String> {
    let mut out = Vec::new();
    let mut stack = Vec::new();
    let mut was_comma = false;
    for token in tokens {
        match token {
            Token::Number(_) => out.push(token),
            Token::Function(_) | Token::Left => stack.push(token),
            Token::Op(_, _) => {
                while let Some(t) = stack.last() {
                    if matches!(t, Token::Op(_, _)) &&
                        (precedence(t) > precedence(&token) ||
                         (precedence(t) == precedence(&token) && !right_associative(&token))) {
                        out.push(stack.pop().unwrap());
                    } else { break; }
                }
                stack.push(token);
            }
            Token::Right => {
                let mut found = false;
                while let Some(t) = stack.pop() {
                    if matches!(t, Token::Left) { found = true; break; }
                    out.push(t);
                }
                if !found { return Err(PARENS.into()); }
                if matches!(stack.last(), Some(Token::Function(_))) { out.push(stack.pop().unwrap()); }
            }
            Token::Comma => {
                if was_comma { return Err("Syntax Error: Empty argument".into()); }
                while let Some(t) = stack.last() {
                    if matches!(t, Token::Left) { break; }
                    out.push(stack.pop().unwrap());
                }
                if !matches!(stack.last(), Some(Token::Left)) { return Err(PARENS.into()); }
                // A separator is accepted in a function call, or in a top-level group.
                if stack.len() >= 2 && !matches!(stack[stack.len()-2], Token::Function(_)) {
                    return Err(PARENS.into());
                }
                was_comma = true;
                continue;
            }
        }
        was_comma = false;
    }
    while let Some(t) = stack.pop() {
        if matches!(t, Token::Left | Token::Right) { return Err(PARENS.into()); }
        out.push(t);
    }
    Ok(out)
}

fn factorial(x: f64) -> Result<f64, String> {
    if x < 0.0 || x.fract() != 0.0 { return Err(DOMAIN.into()); }
    if x > 170.0 { return Ok(f64::INFINITY); }
    let mut n = 1.0;
    for i in 1..=(x as u64) { n *= i as f64; }
    Ok(n)
}

fn apply_function(name: &str, a: f64, b: f64, radians: bool) -> Result<f64, String> {
    let angle = if radians { a } else { a.to_radians() };
    let result = match name {
        "sin" => angle.sin(), "cos" => angle.cos(), "tan" => angle.tan(),
        "csc" => angle.sin().recip(), "sec" => angle.cos().recip(), "cot" => angle.tan().recip(),
        "sinh" => a.sinh(), "cosh" => a.cosh(), "tanh" => a.tanh(),
        "asin" => a.asin(), "acos" => a.acos(), "atan" => a.atan(),
        "acsc" => a.recip().asin(), "asec" => a.recip().acos(), "acot" => a.recip().atan(),
        "ln" => a.ln(), "log2" => a.log2(), "log10" => a.log10(),
        "sqrt" => a.sqrt(), "ceil" => a.ceil(), "floor" => a.floor(),
        "abs" => a.abs(), "round" => a.round(), "exp" => a.exp(), "exp2" => a.exp2(),
        "log" => a.log(b), "nroot" => a.powf(b.recip()),
        "rad" => a.to_radians(), "deg" => a.to_degrees(),
        _ => return Err(format!("Syntax Error: Unknown function '{}'", name)),
    };
    if result.is_finite() { Ok(result) } else { Err(DOMAIN.into()) }
}

fn evaluate(tokens: Vec<Token>, radians: bool) -> Result<f64, String> {
    let mut stack: Vec<f64> = Vec::new();
    for t in tokens {
        let value = match t {
            Token::Number(x) => { stack.push(x); continue; }
            Token::Op(op, prefix) => {
                let b = stack.pop().ok_or(PARSER)?;
                if prefix {
                    match op { '+' => b, '-' => -b, '!' => 1.0, _ => return Err(PARSER.into()) }
                } else if op == '!' {
                    factorial(b)?
                } else {
                    let a = stack.pop().ok_or(PARSER)?;
                    match op {
                        '+' => a+b, '-' => a-b, '*' => a*b,
                        '/' => { if b == 0.0 { return Err("Math Error: Divide by zero error!".into()); } a/b },
                        '%' => a%b, '^' => a.powf(b),
                        _ => return Err(PARSER.into()),
                    }
                }
            }
            Token::Function(name) => {
                let arity = if name == "log" || name == "nroot" { 2 } else { 1 };
                if stack.len() < arity { return Err(format!("Parser Error: To few arguments for function, need {}", arity)); }
                let b = if arity == 2 { stack.pop().unwrap() } else { 0.0 };
                let a = stack.pop().unwrap();
                apply_function(&name, a, b, radians)?
            }
            _ => return Err(PARSER.into()),
        };
        if !value.is_finite() { return Err(too_large()); }
        stack.push(value);
    }
    if stack.len() == 1 { Ok(stack[0]) } else { Err(PARSER.into()) }
}

pub fn calculate(input: &str, previous: Option<f64>, radians: bool) -> Result<f64, String> {
    let mut input = input.trim().replace(' ', "");
    if input.is_empty() { return Ok(0.0); }
    if input == "help" { return Err(help()); }
    let mut depth = 0_i32;
    for c in input.chars() {
        if c == '(' { depth += 1; }
        if c == ')' { depth -= 1; }
        if depth < 0 { return Err(PARENS.into()); }
    }
    for _ in 0..depth { input.push(')'); }
    evaluate(postfix(lex(&input, previous)?)?, radians)
}
EOF
cat > src/display.rs <<'EOF'
fn group(s: &str) -> String {
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if i != 0 && (s.len() - i) % 3 == 0 { out.push(','); }
        out.push(c);
    }
    out
}

fn digit(n: f64) -> char {
    b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[(n as usize).min(35)] as char
}

pub fn number(x: f64, precision: usize, radix: u32) -> String {
    let decimal = format!("{:.*}", precision, x);
    if radix == 10 {
        if let Some((integer, fraction)) = decimal.split_once('.') {
            if let Some(integer) = integer.strip_prefix('-') {
                format!("-{}.{}", group(integer), fraction)
            } else {
                format!("{}.{}", group(integer), fraction)
            }
        } else { decimal }
    } else {
        let x = decimal.parse::<f64>().unwrap_or(x);
        if !x.is_finite() { return decimal; }
        let negative = x.is_sign_negative();
        let abs = x.abs();
        let mut integer = abs.trunc();
        let mut digits = Vec::new();
        if integer == 0.0 { digits.push('0'); }
        while integer >= 1.0 {
            digits.push(digit(integer % radix as f64));
            integer = (integer / radix as f64).floor();
        }
        let mut whole = String::new();
        if negative { whole.push('-'); }
        whole.extend(digits.iter().rev());
        whole = format!("{:>10}", whole);
        let mut fraction = abs.fract();
        let mut frac_digits = String::new();
        for _ in 0..precision {
            fraction *= radix as f64;
            frac_digits.push(digit(fraction.trunc()));
            fraction = fraction.fract();
            if fraction == 0.0 { break; }
        }
        format!("{}.{}", group(&whole), frac_digits)
    }
}
