use std::env;
use std::path::Path;

pub struct Options {
    pub fix: usize,
    pub base: u32,
    pub radians: bool,
    pub input: Option<String>,
}

const MORE: &str = "For more information, try '--help'.\n";
const VALUES: &str = "  [possible values: degree, radian, gradian]\n";

fn long_help(program: &str) -> String {
    format!("Calculator REPL similar to bc(1)\n\nUsage: {} [OPTIONS] [INPUT]\n\nArguments:\n  [INPUT]  Optional expression string to run eva in command mode\n\nOptions:\n  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]\n  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]\n  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]\n  -h, --help                     Print help\n  -V, --version                  Print version\n", program)
}

fn option_name(key: char) -> &'static str {
    match key {
        'f' => "--fix <FIX>", 'b' => "--base <RADIX>", 'a' => "--angle_unit <angle_unit>",
        'h' => "--help", 'V' => "--version", _ => "",
    }
}

fn error(message: String) -> Result<Options, i32> {
    eprint!("{}", message);
    Err(2)
}

// Similarity is used only to offer spelling hints for options and angle units.
fn similarity(a: &str, b: &str) -> f64 {
    if a == b { return 1.0; }
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() || b.is_empty() { return 0.0; }
    let distance = (a.len().max(b.len())/2).saturating_sub(1);
    let mut aa = vec![false; a.len()];
    let mut bb = vec![false; b.len()];
    let mut matched = 0;
    for i in 0..a.len() {
        let low = i.saturating_sub(distance);
        let high = (i+distance+1).min(b.len());
        for j in low..high {
            if !bb[j] && a[i] == b[j] { aa[i]=true; bb[j]=true; matched+=1; break; }
        }
    }
    if matched == 0 { return 0.0; }
    let x: Vec<char> = a.iter().zip(&aa).filter_map(|(&c, &yes)| yes.then_some(c)).collect();
    let y: Vec<char> = b.iter().zip(&bb).filter_map(|(&c, &yes)| yes.then_some(c)).collect();
    let transpositions = x.iter().zip(&y).filter(|(x,y)| x != y).count() as f64 / 2.0;
    let m = matched as f64;
    let score = (m/a.len() as f64 + m/b.len() as f64 + (m-transpositions)/m)/3.0;
    if score > 0.7 {
        let prefix = a.iter().zip(&b).take_while(|(a,b)| a == b).count().min(4);
        score + prefix as f64 * 0.1 * (1.0-score)
    } else { score }
}
fn suggestion<'a>(value: &str, possibilities: &'a [&'a str]) -> Option<&'a str> {
    possibilities.iter().copied().map(|x| (x,similarity(value,x)))
        .filter(|(_,s)| *s > 0.8)
        .max_by(|a,b| a.1.partial_cmp(&b.1).unwrap()).map(|x| x.0)
}

fn unexpected(arg: &str, program: &str, used: &[char]) -> String {
    let mut message = format!("error: unexpected argument '{}' found\n", arg);
    let mut usage = format!("{} [OPTIONS] [INPUT]", program);
    let possible = if arg.starts_with("--") {
        suggestion(arg.trim_start_matches('-'), &["fix", "base", "angle_unit", "help", "version"])
    } else { None };
    if let Some(hint) = possible {
        message.push_str(&format!("\n  tip: a similar argument exists: '--{}'\n", hint));
        let key = match hint { "fix"=>'f', "base"=>'b', "angle_unit"=>'a', "help"=>'h', _=>'V' };
        usage = specific_usage(program, used, Some(key));
    } else if arg.starts_with('-') && arg != "-" {
        message.push_str(&format!("\n  tip: to pass '{}' as a value, use '-- {}'\n", arg, arg));
    }
    format!("{}\nUsage: {}\n\n{}", message, usage, MORE)
}

fn specific_usage(program: &str, used: &[char], extra: Option<char>) -> String {
    let mut s = program.to_string();
    for key in ['f','b','a','h','V'] {
        if used.contains(&key) || extra == Some(key) { s.push(' '); s.push_str(option_name(key)); }
    }
    s.push_str(" [INPUT]");
    s
}

fn missing(key: char) -> String {
    format!("error: a value is required for '{}' but none was supplied\n{}\n{}", option_name(key), if key == 'a' {VALUES} else {""}, MORE)
}
fn repeated(key: char, program: &str) -> String {
    format!("error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] [INPUT]\n\n{}", option_name(key), program, MORE)
}
fn validate(opts: &mut Options, key: char, value: &str) -> Result<(), String> {
    if key == 'a' {
        if !["degree", "radian", "gradian"].contains(&value) {
            let mut msg = format!("error: invalid value '{}' for '{}'\n{}", value, option_name(key), VALUES);
            if let Some(hint) = suggestion(value, &["degree", "radian", "gradian"]) {
                msg.push_str(&format!("\n  tip: a similar value exists: '{}'\n", hint));
            }
            return Err(format!("{}\n{}", msg, MORE));
        }
        opts.radians = value == "radian";
    } else {
        let parsed = value.parse::<u64>();
        let range = if key == 'f' {64} else {36};
        let (n, reason) = match parsed {
            Ok(n) if (1..=range).contains(&n) => (n, None),
