                    return error(format!("error: unexpected value '{}' for '{}' found; no more were expected\n\nUsage: {}\n\n{}", v, option_name(key), specific_usage(program, &used, Some(key)), MORE));
                }
                if key == 'h' { print!("{}", long_help(program)); } else { println!("eva 0.3.1"); }
                return Err(0);
