import os,pty,select,subprocess,time,tempfile,termios,fcntl,struct

def drain(master,period=.3):
 out=b'';end=time.monotonic()+period
 while time.monotonic()<end:
  if select.select([master],[],[],max(0,end-time.monotonic()))[0]:
   try:data=os.read(master,65536)
   except OSError:break
   if not data:break
   out+=data
   if b'\x1b[6n' in data:os.write(master,b'\x1b[1;1R')
 return out
with tempfile.TemporaryDirectory(prefix='eva-tty-') as d:
 env=dict(os.environ,TERM='xterm-256color',HOME=d,XDG_DATA_HOME=d+'/data',XDG_CACHE_HOME=d+'/cache')
 master,slave=pty.openpty();fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',24,80,0,0))
 p=subprocess.Popen(['./executable'],stdin=slave,stdout=slave,stderr=slave,env=env);os.close(slave)
 print('Startup:',repr(drain(master)))
 for data in [b'1+2',b'\r',b'_*4\r',b'sqrt(-1)\r',b'\x04']:
  os.write(master,data);print('Sent',repr(data),'Read',repr(drain(master)))
 try:p.wait(timeout=2)
 except subprocess.TimeoutExpired:p.kill();p.wait()
 print('Exit',p.returncode);os.close(master)
 for a in [['--help'],['--base','99'],['1+2']]:
  master,slave=pty.openpty();fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',24,80,0,0))
  p=subprocess.Popen(['./executable']+a,stdin=slave,stdout=slave,stderr=slave,env=env);os.close(slave)
  print('TTY',a,repr(drain(master)));p.wait();os.close(master)
