fn quoted(line: &str, colors: &[&str]) -> String {
    let mut out = String::new();
    let mut remaining = line;
    let mut i = 0;
    while let Some(start) = remaining.find('\'') {
        out.push_str(&remaining[..start+1]);
        remaining = &remaining[start+1..];
        if let Some(end) = remaining.find('\'') {
            out.push_str(&paint(&remaining[..end], colors.get(i).copied().unwrap_or("1")));
            out.push('\'');
            remaining = &remaining[end+1..];
            i += 1;
        } else { out.push_str(remaining); return out; }
    }
    out.push_str(remaining);
    out
}
pub fn help(text: &str) -> String {
    if !enabled(false) { return text.to_string(); }
    let mut out = String::new();
    for line in text.lines() {
        let colored = if line.starts_with("Usage:") { usage(line) }
        else if line == "Arguments:" || line == "Options:" { format!("\x1b[1m\x1b[4m{}\x1b[0m",line) }
        else if line.starts_with("  -") {
            let mut s = String::from("  ");
            let (short, rest) = line[2..].split_once(", ").unwrap();
            let (long, rest) = rest.split_once(' ').unwrap();
            s.push_str(&paint(short,"1")); s.push_str(", "); s.push_str(&paint(long,"1"));
            s.push(' '); s.push_str(rest); s
        } else { line.to_string() };
        out.push_str(&colored); out.push('\n');
    }
    out
}
pub fn error(text: &str) -> String {
    if !enabled(true) { return text.to_string(); }
    let mut out = String::new();
    for line in text.lines() {
        let colored = if line.starts_with("error:") {
            let mut s = String::from("\x1b[1m\x1b[31merror:\x1b[0m");
            s.push_str(&quoted(&line[6..], &["33", "1"])); s
        } else if line.starts_with("Usage:") { usage(line) }
        else if let Some(values) = line.strip_prefix("  [possible values: ") {
            let mut s = String::from("  [possible values: ");
            for (i, value) in values.trim_end_matches(']').split(", ").enumerate() {
                if i>0 {s.push_str(", ");} s.push_str(&paint(value,"32"));
            }
            s.push(']'); s
        } else if line.starts_with("  tip:") {
