//! A small terminal line editor. No platform-specific third-party library is needed.
use std::{env, fs, io::{self, Read, Write}, mem::MaybeUninit, path::Path};
use crate::calculator;

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    input: u32, output: u32, control: u32, local: u32,
    line: u8, chars: [u8;32], input_speed: u32, output_speed: u32,
}
#[repr(C)]
struct WindowSize { rows: u16, cols: u16, x: u16, y: u16 }
unsafe extern "C" {
    fn tcgetattr(fd: i32, term: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, action: i32, term: *const Termios) -> i32;
    fn cfmakeraw(term: *mut Termios);
    fn ioctl(fd: i32, request: u64, arg: *mut WindowSize) -> i32;
}
struct Raw { old: Termios }
impl Raw {
    fn start() -> Option<Self> {
        unsafe {
            let mut old = MaybeUninit::<Termios>::uninit();
            if tcgetattr(0, old.as_mut_ptr()) != 0 { return None; }
            let old = old.assume_init();
            let mut new = old;
            cfmakeraw(&mut new);
            new.chars[6] = 1; // VMIN
            new.chars[5] = 0; // VTIME
            if tcsetattr(0, 0, &new) != 0 { return None; }
            Some(Self { old })
        }
    }
}
impl Drop for Raw {
    fn drop(&mut self) { unsafe { tcsetattr(0, 0, &self.old); } }
}

pub enum Line { Text(String), Eof, Interrupted, Unavailable }
pub fn supported() -> bool {
    !matches!(env::var("TERM").unwrap_or_default().as_str(), "dumb" | "emacs" | "cons25")
}
fn emit(s: &str) { print!("{}",s); let _ = io::stdout().flush(); }
fn color(s: &str, n: u8) -> String { format!("\x1b[{}m{}\x1b[0m",n,s) }
fn highlight(s: &str) -> String {
    let normal = s.trim().replace(' ', "");
    if normal != "help" && calculator::calculate(s, None, false).is_err() { return color(s,31); }
    let mut out = String::new();
    let v: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < v.len() {
        let c = v[i];
        if c.is_ascii_alphabetic() {
            let start = i;
            while i < v.len() && v[i].is_ascii_alphanumeric() { i+=1; }
            let word: String = v[start..i].iter().collect();
            if calculator::FUNCTIONS.contains(&word.as_str()) && v.get(i) == Some(&'(') { out.push_str(&color(&word,34)); }
            else if word == "pi" || word == "e" { out.push_str(&color(&word,33)); }
            else if word == "help" { out.push_str(&color(&word,36)); }
            else { out.push_str(&word); }
        } else {
            if "+-*/^!%.,".contains(c) { out.push_str(&color(&c.to_string(),35)); }
            else { out.push(c); }
            i += 1;
        }
    }
    out
}
fn width(c: char) -> usize {
    let n = c as u32;
    if c == '\n' || c == '\r' { 0 }
    else if (0x300..=0x36f).contains(&n) { 0 }
    else if (0x1100..=0x115f).contains(&n) || (0x2e80..=0xa4cf).contains(&n) ||
            (0xac00..=0xd7a3).contains(&n) || (0xf900..=0xfaff).contains(&n) ||
            (0xff01..=0xff60).contains(&n) || (0x1f300..=0x1faff).contains(&n) { 2 }
    else { 1 }
}
fn columns() -> usize {
    let mut w = WindowSize { rows:0, cols:0, x:0, y:0 };
    unsafe { ioctl(1, 0x5413, &mut w); }
    if w.cols == 0 { 80 } else { w.cols as usize }
}
struct Screen { rows: usize, cursor_row: usize, cols: usize }
impl Screen {
    fn draw(&mut self, line: &[char], cursor: usize, history: &[String], hints: bool) {
        let text: String = line.iter().collect();
        let mut hint = String::new();
        if hints && cursor == line.len() && !text.is_empty() {
            if let Some(s) = history.iter().rev().find(|s| s.starts_with(&text) && s.len()>text.len()) {
                hint = s[text.len()..].to_string();
            }
        }
        let mut out = String::from("\x1b[?2026h");
        if self.cursor_row > 0 { out.push_str(&format!("\x1b[{}A",self.cursor_row)); }
        out.push('\r');
        if self.rows > 0 { out.push_str("\x1b[J"); } else { out.push_str("\x1b[K"); }
        out.push_str("> "); out.push_str(&highlight(&text));
        if !hint.is_empty() { out.push_str(&color(&hint,90)); }
        let total = 2 + line.iter().map(|c| width(*c)).sum::<usize>() + hint.chars().map(width).sum::<usize>();
        let target = 2 + line.iter().take(cursor).map(|c| width(*c)).sum::<usize>();
        let rows = total / self.cols;
        let target_row = target / self.cols;
        if rows > target_row { out.push_str(&format!("\x1b[{}A", rows-target_row)); }
        out.push('\r');
        let col = target % self.cols;
        if col > 0 { out.push_str(&format!("\x1b[{}C",col)); }
        out.push_str("\x1b[?2026l");
        emit(&out);
        self.rows = rows; self.cursor_row = target_row;
    }
    fn move_cursor(&mut self, line: &[char], cursor: usize) {
        let target = 2 + line.iter().take(cursor).map(|c| width(*c)).sum::<usize>();
        let row = target/self.cols;
        let mut out = String::new();
        if self.cursor_row>row { out.push_str(&format!("\x1b[{}A",self.cursor_row-row)); }
        if self.cursor_row<row { out.push_str(&format!("\x1b[{}B",row-self.cursor_row)); }
        out.push('\r');
        if target%self.cols>0 { out.push_str(&format!("\x1b[{}C",target%self.cols)); }
        emit(&out); self.cursor_row = row;
    }
}
fn read_byte(input: &mut impl Read) -> Option<u8> {
