fn read_char(first: u8, input: &mut impl Read) -> Option<char> {
    if first < 128 { return Some(first as char); }
    let length = if first < 0xe0 {2} else if first < 0xf0 {3} else {4};
    let mut bytes=vec![first];
    for _ in 1..length { bytes.push(read_byte(input)?); }
