fn completion(line: &[char], cursor: usize) -> Option<(usize, String)> {
    let mut start = cursor;
    while start>0 && !" \t'\"=<>;|&(".contains(line[start-1]) { start -= 1; }
    let word: String = line[start..cursor].iter().collect();
    let (dir, prefix) = word.rsplit_once('/').map_or(("",word.as_str()), |(d,p)| (d,p));
    let actual = if dir.is_empty() {".".to_string()} else if dir.starts_with('~') {
        dir.replacen('~', &env::var("HOME").unwrap_or_default(), 1)
    } else {dir.to_string()};
    let entries = fs::read_dir(&actual).ok()?;
    let mut choices = Vec::new();
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        if name.starts_with(prefix) && (!name.starts_with('.') || prefix.starts_with('.')) {
            let is_dir = Path::new(&actual).join(&name).is_dir();
            let mut choice = if dir.is_empty() {name} else {format!("{}/{}",dir,name)};
            if is_dir {choice.push('/');}
            choices.push(choice);
        }
    }
    choices.sort();
    if choices.is_empty() { return None; }
    let mut common = choices[0].clone();
    for choice in &choices[1..] {
        let n=common.chars().zip(choice.chars()).take_while(|(a,b)|a==b).count();
