use std::{env, fs, io::{self, Read, Write}, mem::MaybeUninit, path::Path};
use crate::calculator;

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    input: u32, output: u32, control: u32, local: u32,
    line: u8, chars: [u8;32], input_speed: u32, output_speed: u32,
}
#[repr(C)]
struct WindowSize { rows: u16, cols: u16, x: u16, y: u16 }
unsafe extern "C" {
    fn tcgetattr(fd: i32, term: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, action: i32, term: *const Termios) -> i32;
    fn cfmakeraw(term: *mut Termios);
    fn ioctl(fd: i32, request: u64, arg: *mut WindowSize) -> i32;
}
struct Raw { old: Termios }
impl Raw {
    fn start() -> Option<Self> {
        unsafe {
            let mut old = MaybeUninit::<Termios>::uninit();
            if tcgetattr(0, old.as_mut_ptr()) != 0 { return None; }
            let old = old.assume_init();
            let mut new = old;
            cfmakeraw(&mut new);
            new.chars[6] = 1; // VMIN
            new.chars[5] = 0; // VTIME
            if tcsetattr(0, 0, &new) != 0 { return None; }
            Some(Self { old })
        }
    }
}
impl Drop for Raw {
    fn drop(&mut self) { unsafe { tcsetattr(0, 0, &self.old); } }
}

pub enum Line { Text(String), Eof, Interrupted, Unavailable }
pub fn supported() -> bool {
    !matches!(env::var("TERM").unwrap_or_default().as_str(), "dumb" | "emacs" | "cons25")
