fn color(s: &str, n: u8) -> String { format!("\x1b[{}m{}\x1b[0m",n,s) }
fn highlight(s: &str) -> String {
    let normal = s.trim().replace(' ', "");
    if normal != "help" && calculator::calculate(s, None, false).is_err() { return color(s,31); }
    let mut out = String::new();
    let v: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < v.len() {
        let c = v[i];
        if c.is_ascii_alphabetic() {
            let start = i;
            while i < v.len() && v[i].is_ascii_alphanumeric() { i+=1; }
            let word: String = v[start..i].iter().collect();
            if calculator::FUNCTIONS.contains(&word.as_str()) && v.get(i) == Some(&'(') { out.push_str(&color(&word,34)); }
            else if word == "pi" || word == "e" { out.push_str(&color(&word,33)); }
            else if word == "help" { out.push_str(&color(&word,36)); }
            else { out.push_str(&word); }
        } else {
            if "+-*/^!%.,".contains(c) { out.push_str(&color(&c.to_string(),35)); }
            else { out.push(c); }
            i += 1;
        }
    }
    out
}
fn width(c: char) -> usize {
    let n = c as u32;
    if c == '\n' || c == '\r' { 0 }
