struct Screen { rows: usize, cursor_row: usize, cols: usize }
impl Screen {
    fn draw(&mut self, line: &[char], cursor: usize, history: &[String], hints: bool) {
        let text: String = line.iter().collect();
        let mut hint = String::new();
        if hints && cursor == line.len() && !text.is_empty() {
            if let Some(s) = history.iter().rev().find(|s| s.starts_with(&text) && s.len()>text.len()) {
