        out.push_str("> "); out.push_str(&highlight(&text));
        if !hint.is_empty() { out.push_str(&color(&hint,90)); }
        let total = 2 + line.iter().map(|c| width(*c)).sum::<usize>() + hint.chars().map(width).sum::<usize>();
