        if self.cursor_row<row { out.push_str(&format!("\x1b[{}B",row-self.cursor_row)); }
        out.push('\r');
        if target%self.cols>0 { out.push_str(&format!("\x1b[{}C",target%self.cols)); }
        emit(&out); self.cursor_row = row;
    }
